describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 → sum = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000) = 600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1000);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -500 clamped to 0 + min(300, 1000)=300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining 9000
      // Second: 10% of 9000 = 900
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const big = new FixedAmountDiscountPolicy(800);
      const pct = new PercentageDiscountPolicy(50);

      const bigFirst = new CompositeDiscountPolicy([big, pct], "chain");
      const pctFirst = new CompositeDiscountPolicy([pct, big], "chain");

      // bigFirst: 800 off 1000 → remaining 200, then 50% of 200=100 → total 900
      expect(bigFirst.computeDiscountCents(1000)).toBe(900);
      // pctFirst: 50% of 1000=500 → remaining 500, then min(800,500)=500 → total 1000
      expect(pctFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("stops when remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // First eats entire 1000, remaining=0, second gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 and caps at remaining", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // negative clamped to 0, remaining still 1000, then min(300,1000)=300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

