        getRate: vi.fn().mockResolvedValue(0.0875),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=10000, discount=1000, discounted=9000
      // tax = 8.75% of 9000 = 787.5 → 787
      expect(result.totals.taxCents).toBe(787);
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider failure", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(product("a", 1000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(
        cart.checkout({ asyncTaxProvider: provider }),
      ).rejects.toThrow("tax service down");
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(200),
        shippingCalculator: new FlatShippingCalculator(300),
        region: "US",
      });
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1100) // a
          .mockResolvedValueOnce(2200), // b
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // subtotal = 1100*2 + 2200*1 = 4400
      // discount = min(200, 4400) = 200
      // discounted = 4200
      // tax = 10% of 4200 = 420
      // shipping = 300
      expect(result.totals.subtotalCents).toBe(4400);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(420);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(4200 + 420 + 300);
    });

    it("first inventory denial wins with multiple items", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);
      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "b is gone" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });

    it("uses sync tax when no asyncTaxProvider", async () => {
      const cart = new Cart({
        taxCalculator: new RegionalTaxCalculator({ "US": 0.05 }),
        region: "US",
      });
      cart.add(product("a", 10000), 1);
      const result = await cart.checkout();
      expect(result.totals.taxCents).toBe(500);
    });

    it("generates default message for unavailable without reason", async () => {
      const cart = new Cart();
      cart.add(product("x", 1000), 3);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).message).toContain("insufficient stock");
        expect((err as InventoryError).available).toBeUndefined();
      }
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 → 33
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-500)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(999999999)).toBe(Math.floor(999999999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("returns amount when subtotal > amount", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when amount > subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns subtotal when amount == subtotal", () => {
    const p = new FixedAmountDiscountPolicy(1000);
    expect(p.computeDiscountCents(1000)).toBe(1000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 → sum = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000) = 600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1000);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -500 clamped to 0 + min(300, 1000)=300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining 9000
      // Second: 10% of 9000 = 900
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const big = new FixedAmountDiscountPolicy(800);
      const pct = new PercentageDiscountPolicy(50);

      const bigFirst = new CompositeDiscountPolicy([big, pct], "chain");
      const pctFirst = new CompositeDiscountPolicy([pct, big], "chain");

      // bigFirst: 800 off 1000 → remaining 200, then 50% of 200=100 → total 900
      expect(bigFirst.computeDiscountCents(1000)).toBe(900);
      // pctFirst: 50% of 1000=500 → remaining 500, then min(800,500)=500 → total 1000
      expect(pctFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("stops when remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // First eats entire 1000, remaining=0, second gets 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 and caps at remaining", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // negative clamped to 0, remaining still 1000, then min(300,1000)=300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

