toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weight?: number, qty = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeShippingCents([line("a")], 10000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when subtotal >= freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
    expect(calc.computeShippingCents([line("a")], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal < freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a")], 4999)).toBe(599);
  });

  it("accepts freeOverCents of 0 (always free)", () => {
    const calc = new FlatShippingCalculator(599, 0);
    expect(calc.computeShippingCents([line("a")], 0)).toBe(0);
  });

  it("accepts flatCents of 0", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a")], 1000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 100 }], 1.5),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a")], 10000)).toBe(0);
  });

  it("selects correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([line("a", 400)], 10000)).toBe(300);
    // 500g → first bracket boundary
    expect(calc.computeShippingCents([line("a", 500)], 10000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([line("a", 501)], 10000)).toBe(500);
    // 1000g → second bracket boundary
    expect(calc.computeShippingCents([line("a", 1000)], 10000)).toBe(500);
    // 3000g → third bracket
    expect(calc.computeShippingCents([line("a", 3000)], 10000)).toBe(1000);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 400)], 10000)).toBe(300);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 1000, costCents: 500 }],
      2000,
    );
    expect(calc.computeShippingCents([line("a", 2000)], 10000)).toBe(2000);
  });

  it("defaults overflow to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 5000)], 10000)).toBe(500);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // 200*2 + 300*1 = 700 → second bracket
    const lines = [line("a", 200, 2), line("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 10000)).toBe(500);
  });
});

