import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.itemCount).toBe(1);
    });

    it("merges quantities for same product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // mutating snapshot doesn't affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        taxCalculator: new RegionalTaxCalculator({ "US": 0.10 }),
        region: "US",
      });
      cart.add(product("a", 10000), 1);
      const totals = cart.totals();
      // subtotal = 10000
      // discount = 10% of 10000 = 1000
      // discounted = 9000
      // tax = 10% of 9000 = 900
      expect(totals.subtotalCents).toBe(10000);
      expect(totals.discountCents).toBe(1000);
      expect(totals.taxCents).toBe(900);
      expect(totals.totalCents).toBe(9000 + 900);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negativeTax: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator: negativeTax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShipping: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator: negShipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("integrates discount + tax + shipping", () => {
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(500),
        taxCalculator: new RegionalTaxCalculator({ "US": 0.08 }),
        shippingCalculator: new FlatShippingCalculator(499),
        region: "US",
      });
      cart.add(product("a", 2000), 1);
      cart.add(product("b", 1000), 1);
      const totals = cart.totals();
      // subtotal = 3000
      // discount = 500
      // discounted = 2500
      // tax = 8% of 2500 = 200
      // shipping = 499
      expect(totals.subtotalCents).toBe(3000);
      expect(totals.discountCents).toBe(500);
      expect(totals.taxCents).toBe(200);
      expect(totals.shippingCents).toBe(499);
      expect(totals.totalCents).toBe(2500 + 200 + 499);
    });

    it("uses default config (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });

    it("shipping receives discounted subtotal", () => {
      const shippingCalc: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(500),
        shippingCalculator: shippingCalc,
      });
      cart.add(product("a", 2000), 1);
      cart.totals();
      expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1500, // discounted subtotal
      );
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for simple checkout", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws InventoryError when item unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.message).toBe("sold out");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 10);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("passes when available and no partial denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("passes when availableQuantity >= requested", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 5 }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        region: "US-CA",
      });
      cart.add(product("a", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // subtotal=10000, discount=1000, discounted=9000
      // tax = 8.75% of 9000 = 787.5 → 787
      expect(result.totals.taxCents).toBe(787);
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider failure", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(product("a", 1000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(
        cart.checkout({ asyncTaxProvider: provider }),
      ).rejects.toThrow("tax service down");
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(200),
        shippingCalculator: new FlatShippingCalculator(300),
        region: "US",
      });
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1100) // a
          .mockResolvedValueOnce(2200), // b
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // subtotal = 1100*2 + 2200*1 = 4400
      // discount = min(200, 4400) = 200
      // discounted = 4200
      // tax = 10% of 4200 = 420
      // shipping = 300
      expect(result.totals.subtotalCents).toBe(4400);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(420);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(4200 + 420 + 300);
    });

    it("first inventory denial wins with multiple items", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);
      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "b is gone" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });

    it("uses sync tax when no asyncTaxProvider", async () => {
      const cart = new Cart({
        taxCalculator: new RegionalTaxCalculator({ "US": 0.05 }),
        region: "US",
      });
      cart.add(product("a", 10000), 1);
      const result = await cart.checkout();
      expect(result.totals.taxCents).toBe(500);
    });

    it("generates default message for unavailable without reason", async () => {
      const cart = new Cart();
      cart.add(product("x", 1000), 3);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).message).toContain("insufficient stock");
        expect((err as InventoryError).available).toBeUndefined();
      }
    });
  });
});

